class Solution:
    def bubbleSort(self, arr=None, n=None, *args):
        if arr is None or n is None:
            return None
        for i in range(n):
            for j in range(0, n - i - 1):
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]
        return arr

