from typing import List

class Solution:
    def insertionSort(self, arr: List[int] = None, n: int = None, *args):
        if arr is None or n is None:
            return None
        for i in range(1, n):
            key = arr[i]
            j = i - 1
            while j >= 0 and arr[j] > key:
                arr[j + 1] = arr[j]
                j -= 1
            arr[j + 1] = key
        return arr

step_01___basics_armstrong_number:
class Solution:
    def armstrongNumber(self, n):
        original = n
        t = abs(n)
        total = 0
        if t == 0:
            total = 0
        else:
            while t > 0:
                d = t % 10
                total += d ** 3
                t //= 10
        return str(total == original).lower()

step_02___sorting_techniques_quick_sort:
from typing import List

class Solution:
    def quickSort(self, arr: List[int], low: int, high: int) -> None:
        if low < high:
            pivot = arr[high]
            i = low - 1
            for j in range(low, high):
                if arr[j] <= pivot:
                    i += 1
                    arr[i], arr[j] = arr[j], arr[i]
            arr[i + 1], arr[high] = arr[high], arr[i + 1]
            pi = i + 1
            self.quickSort(arr, low, pi - 1)
            self.quickSort(arr, pi + 1, high)

