from typing import List

class Solution:
    def selectionSort(self, arr: List[int] = None, n: int = None, *args):
        if arr is None or n is None:
            return None
        for i in range(n):
            min_index = i
            for j in range(i + 1, n):
                if arr[j] < arr[min_index]:
                    min_index = j
            if min_index != i:
                arr[i], arr[min_index] = arr[min_index], arr[i]
        return arr

step_01___basics_reverse_number:
class Solution:
    def reverse(self, x: int) -> int:
        low, high = -(2**31), (2**31)
        negative = x < 0
        n = abs(x)
        rev = 0
        while n > 0:
            rev = rev * 10 + n % 10
            n //= 10
        if negative:
            rev = -rev
        if rev not in range(low, high):
            return 0
        return rev

