step_01___basics_lcm_gcd:
class Solution:
    def lcmAndGcd(self, A, B):
        a, b = abs(A), abs(B)
        gcd = 1
        for i in range(1, min(a, b) + 1):
            if a % i == 0 and b % i == 0:
                gcd = i
        lcm = (A * B) // gcd
        return [lcm, gcd]

