class Solution:
    def isPalindrome(self, x: int = 0) -> bool:
        if x < 0:
            return False
        original = x
        n = x
        reversed_num = 0
        while n > 0:
            digit = n % 10
            reversed_num = reversed_num * 10 + digit
            n //= 10
        return reversed_num == original

