from typing import List


class Solution:
    def moveZeroes(self, nums: List[int]) -> None:
        n = len(nums)
        # Bubble-sort style: repeatedly swap adjacent (zero, non-zero) pairs
        # so zeros "bubble" toward the end. Stable, O(n^2).
        for i in range(n):
            for j in range(n - i - 1):
                if nums[j] == 0 and nums[j + 1] != 0:
                    nums[j], nums[j + 1] = nums[j + 1], nums[j]

