class Solution:
    def getFloorAndCeil(self, arr, n, x):
        floor_val = -1
        ceil_val = -1
        for val in arr[:n]:
            if val <= x and (floor_val == -1 or val > floor_val):
                floor_val = val
            if val >= x and (ceil_val == -1 or val < ceil_val):
                ceil_val = val
        return [floor_val, ceil_val]

