step_04___binary_search_gas_stations:
from typing import List

class Solution:
    def findSmallestMaxDist(self, stations: List[int], K: int):
        pts = sorted(stations)
        gaps = [pts[i] - pts[i - 1] for i in range(1, len(pts))]
        if not gaps:
            return 0
        counts = [1] * len(gaps)
        for _ in range(K):
            best_i = 0
            best_len = gaps[0] / counts[0]
            for i in range(1, len(gaps)):
                cur = gaps[i] / counts[i]
                if cur > best_len:
                    best_len = cur
                    best_i = i
            counts[best_i] += 1
        return max(gaps[i] / counts[i] for i in range(len(gaps)))

