from typing import List

class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        if m * k > len(bloomDay):
            return -1
        lo, hi = min(bloomDay), max(bloomDay)
        for day in range(lo, hi + 1):
            bouquets = 0
            streak = 0
            for b in bloomDay:
                if b <= day:
                    streak += 1
                    if streak == k:
                        bouquets += 1
                        streak = 0
                else:
                    streak = 0
            if bouquets >= m:
                return day
        return -1

