from typing import List, Optional, Dict, Set, Tuple

class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        n = len(nums)
        # Naive linear scan: check every index and see if it is bigger
        # than both of its neighbours (treating out-of-range neighbours
        # as -infinity), instead of jumping around with binary search.
        for i in range(n):
            left_ok = (i == 0) or (nums[i] > nums[i - 1])
            right_ok = (i == n - 1) or (nums[i] > nums[i + 1])
            if left_ok and right_ok:
                return i
        return -1

