class Solution:
    def minTime(self, arr: List[int], n: int, k: int):
        total = sum(arr)
        for time in range(0, total + 1):
            painters = 1
            curr = 0
            feasible = True
            for x in arr:
                if x > time:
                    feasible = False
                    break
                if curr + x <= time:
                    curr += x
                else:
                    painters += 1
                    curr = x
            if feasible and painters <= k:
                return time
        return total

