step_04___binary_search_single_element:
from typing import List, Optional, Dict, Set, Tuple

class Solution:
    def singleNonDuplicate(self, nums: List[int]) -> int:
        # Most direct version of the standard technique: walk the same
        # binary-search path as the classic solution (an element is the
        # lone one when both of its "neighbours" differ from it), but
        # written out plainly without the compact one-liners.
        n = len(nums)
        if n == 1:
            return nums[0]
        low, high = 0, n - 1
        while low <= high:
            mid = (low + high) // 2
            left_differs = (mid == 0) or (nums[mid] != nums[mid - 1])
            right_differs = (mid == n - 1) or (nums[mid] != nums[mid + 1])
            if left_differs and right_differs:
                return nums[mid]
            if mid % 2 == 0:
                if mid + 1 < n and nums[mid] == nums[mid + 1]:
                    low = mid + 1
                else:
                    high = mid - 1
            else:
                if nums[mid] == nums[mid - 1]:
                    low = mid + 1
                else:
                    high = mid - 1
        return -1

