class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        def isValid(limit: int) -> bool:
            if any(w > limit for w in weights):
                return False
            day_count, curr = 1, 0
            for item in weights:
                if curr + item <= limit:
                    curr += item
                else:
                    day_count += 1
