        self.mini = -(2 ** 31)

    def myAtoi(self, s: str) -> int:
        # Naive character-by-character simulation using an explicit
        # index instead of lstrip()/slicing helpers.
        i = 0
        n = len(s)
        while i < n and s[i] == ' ':
            i += 1

        sign = 1
        if i < n and s[i] in ('+', '-'):
            if s[i] == '-':
                sign = -1
            i += 1

        digits = ""
        while i < n and s[i].isdigit():
            digits += s[i]
            i += 1

        value = 0
        for ch in digits:
            value = value * 10 + int(ch)
        value *= sign

        if value > self.maxi:
            return self.maxi
        if value < self.mini:
            return self.mini
        return value

