class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.store = {}  # key -> [value, freq, time]
        self.time = 0

    def get(self, key: int) -> int:
        if key not in self.store:
            return -1
        self.time += 1
        self.store[key][1] += 1
        self.store[key][2] = self.time
        return self.store[key][0]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        self.time += 1
        if key in self.store:
            self.store[key][0] = value
            self.store[key][1] += 1
            self.store[key][2] = self.time
            return
        if len(self.store) >= self.capacity:
            evict_key = None
            for k, (v, f, t) in self.store.items():
                if evict_key is None:
                    evict_key = k
                else:
                    ev = self.store[evict_key]
                    if f < ev[1] or (f == ev[1] and t < ev[2]):
                        evict_key = k
            del self.store[evict_key]
        self.store[key] = [value, 1, self.time]


