class Solution:
    def findPath(self, grid: List[List[int]]) -> List[str]:
        n = len(grid)
        if n == 1:
            return []

        ans = []
        visited = [[False] * n for _ in range(n)]

        def helper(i: int, j: int, path: str):
            if i == n - 1 and j == n - 1 and grid[i][j] == 1:
                ans.append(path)
                return
            if 0 <= i < n and 0 <= j < n and grid[i][j] == 1 and not visited[i][j]:
                visited[i][j] = True
                directions = [(-1, 0, 'U'), (0, 1, 'R'), (1, 0, 'D'), (0, -1, 'L')]
                for di, dj, d in directions:
                    helper(i + di, j + dj, path + d)
                visited[i][j] = False
            else:
                return

        helper(0, 0, "")
        return ans

