        n = len(s)
        ans = []

        def is_pal(t: str) -> bool:
            return t == t[::-1]

        def backtrack(start: int, path: List[str]):
            if start == n:
                ans.append(path.copy())
                return
            for end in range(start + 1, n + 1):
                sub = s[start:end]
                if is_pal(sub):
