class Solution:
    def InfixtoPostfix(self, exp: str):
        priority = {'^': 3, '*': 2, '/': 2, '+': 1, '-': 1}
        output = []
        stack = []
        for c in exp:
            if ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9'):
                output.append(c)
            elif c == '(':
                stack.append(c)
            elif c == ')':
                while stack and stack[-1] != '(':
                    output.append(stack.pop())
                if stack:
                    stack.pop()
            else:
                while stack and stack[-1] != '(' and priority.get(stack[-1], 0) >= priority.get(c, 0):
                    output.append(stack.pop())
                stack.append(c)
        while stack:
            output.append(stack.pop())
        return ''.join(output)

