from typing import List, Optional, Dict, Set, Tuple

class Solution:
    def _toPostfixStrictGreater(self, exp: str):
        priority = {'^': 3, '*': 2, '/': 2, '+': 1, '-': 1}
        output = []
        stack = []
        for c in exp:
            if ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9'):
                output.append(c)
            elif c == '(':
                stack.append(c)
            elif c == ')':
                while stack and stack[-1] != '(':
                    output.append(stack.pop())
                if stack:
                    stack.pop()
            else:
                while stack and stack[-1] != '(' and priority.get(stack[-1], 0) > priority.get(c, 0):
                    output.append(stack.pop())
                stack.append(c)
        while stack:
            output.append(stack.pop())
        return ''.join(output)

    def InfixtoPrefix(self, exp: str):
        reversed_exp = exp[::-1]
        swapped_chars = []
        for c in reversed_exp:
            if c == '(':
                swapped_chars.append(')')
            elif c == ')':
                swapped_chars.append('(')
            else:
                swapped_chars.append(c)
        swapped_exp = ''.join(swapped_chars)
        postfix = self._toPostfixStrictGreater(swapped_exp)
        return postfix[::-1]

