        while True:
            smallest = index
            left = 2 * index + 1
            right = 2 * index + 2
            if left < n and self.heap[left] < self.heap[smallest]:
                smallest = left
            if right < n and self.heap[right] < self.heap[smallest]:
                smallest = right
            if smallest == index:
