class Solution:
    def leastInterval(self, tasks: List[str], n: int) -> int:
        counts = Counter(tasks)
        remaining = dict(counts)
        total = len(tasks)
        last_used = {}
        time = 0
        done = 0
        while done < total:
            time += 1
            best_task = None
            best_count = 0
            for t, c in remaining.items():
                if c > 0 and (t not in last_used or time - last_used[t] > n):
                    if c > best_count:
                        best_count = c
                        best_task = t
