class Item:
    def __init__(self, val, w):
        self.value = val
        self.weight = w

class Solution:
    def fractionalknapsack(self, w: int, arr: List[Optional[Item]], n: int) -> float:
        items = list(arr)
        remaining = w
        total = 0.0
        used = [False] * len(items)
        # naive: repeatedly scan for the best available value/weight ratio (no pre-sort)
        for _ in range(len(items)):
            if remaining <= 0:
                break
            best_idx = -1
            best_ratio = -1.0
            for i, it in enumerate(items):
                if used[i]:
                    continue
                ratio = it.value / it.weight
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
            if best_idx == -1:
                break
            used[best_idx] = True
            it = items[best_idx]
            if it.weight <= remaining:
                remaining -= it.weight
                total += it.value
            else:
                total += it.value * (remaining / it.weight)
                remaining = 0
        return total

