        n = len(nums)
        if n <= 1:
            return 0
        dp = [sys.maxsize] * n
        dp[0] = 0
        for i in range(n):
            if dp[i] == sys.maxsize:
                continue
            for step in range(1, nums[i] + 1):
                if i + step < n:
                    if dp[i] + 1 < dp[i + step]:
                        dp[i + step] = dp[i] + 1
        return dp[n - 1]

