        # instead of the level-order (BFS/queue) version.
        if root is None:
            return ""
        parts: List[str] = []

        def helper(node):
            if node is None:
                parts.append('#')
                return
            parts.append(str(node.val))
            helper(node.left)
            helper(node.right)

        helper(root)
        return ','.join(parts)

    def deserialize(self, data: str) -> Optional[TreeNode]:
        if not data:
            return None
        values = iter(data.split(','))

        def helper():
            val = next(values)
            if val == '#':
                return None
            node = TreeNode(int(val))
            node.left = helper()
            node.right = helper()
            return node

        return helper()

