from typing import List


class Solution:
    def findOrder(self, dictionary: List[str], n: int, k: int) -> List[str]:
        # Brute force: build the same precedence graph from adjacent words,
        # but do the topological sort the naive way - repeatedly scan all
        # nodes for one with indegree 0 - instead of using a queue (Kahn's
        # algorithm with an O(k) scan each round instead of O(1) queue pops).
        def node_index(c):
            return ord(c) - ord('a')

        adj = [[] for _ in range(k)]
        indegree = [0 for _ in range(k)]

        for i in range(1, n):
            w1 = dictionary[i - 1]
            w2 = dictionary[i]
            size = min(len(w1), len(w2))
            j = 0
            while j < size and w1[j] == w2[j]:
                j += 1
            if j < size:
                u = node_index(w1[j])
                v = node_index(w2[j])
                adj[u].append(v)
                indegree[v] += 1

        visited = [False] * k
        result = []
        for _ in range(k):
            chosen = -1
            for node in range(k):
                if not visited[node] and indegree[node] == 0:
                    chosen = node
                    break
            if chosen == -1:
                break
            visited[chosen] = True
            result.append(chr(chosen + ord('a')))
            for nxt in adj[chosen]:
                indegree[nxt] -= 1

        return result

