from typing import List
from collections import deque


class Solution:
    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
        # Brute force: run a separate BFS from every '1' cell out to the
        # nearest '0', instead of one shared multi-source BFS starting from
        # all the zeros at once.
        n = len(mat)
        m = len(mat[0])
        SENTINEL = int(1e9)
        distance = [[SENTINEL for _ in range(m)] for _ in range(n)]
        row = [-1, 0, 1, 0]
        col = [0, 1, 0, -1]

        for i in range(n):
            for j in range(m):
                if mat[i][j] == 0:
                    distance[i][j] = 0

        for i in range(n):
            for j in range(m):
                if mat[i][j] == 1:
                    visited = [[False] * m for _ in range(n)]
                    visited[i][j] = True
                    q = deque([(i, j, 0)])
                    found = SENTINEL
                    while q:
                        ci, cj, d = q.popleft()
                        if mat[ci][cj] == 0:
                            found = d
                            break
                        for k in range(4):
                            ni, nj = ci + row[k], cj + col[k]
                            if 0 <= ni < n and 0 <= nj < m and not visited[ni][nj]:
                                visited[ni][nj] = True
                                q.append((ni, nj, d + 1))
                    distance[i][j] = found
        return distance

