class Solution:
    def accountsMerge(self, accounts: List[List[str]]) -> List[List[str]]:
        # Brute force: repeatedly scan every pair of accounts and merge any
        # two whose email sets overlap, instead of using a Disjoint Set
        # (Union-Find).
        groups = []  # list of {"name": str, "emails": set(...)}
        for acc in accounts:
            name = acc[0]
            emails = set(acc[1:])
            groups.append({"name": name, "emails": emails})

        merged = True
        while merged:
            merged = False
            for i in range(len(groups)):
                for j in range(i + 1, len(groups)):
                    if groups[i]["emails"] & groups[j]["emails"]:
                        groups[i]["emails"] |= groups[j]["emails"]
                        del groups[j]
                        merged = True
                        break
                if merged:
                    break

        result = []
        for g in groups:
            if not g["emails"]:
                continue
            result.append([g["name"]] + sorted(g["emails"]))
        return result

