from typing import List, Optional


class Solution:
    def bellman_ford(self, n: int = 1, edges: Optional[List[List[int]]] = None, s: int = 0):
        # Direct/brute-force Bellman-Ford: relax every edge in simple nested
        # loops for up to n rounds (stopping early once nothing changes),
        # then do one more full pass to detect a negative cycle.
        if edges is None:
            edges = []
        INF = int(1e8)
        distance = [INF for _ in range(n)]
        if 0 <= s < n:
            distance[s] = 0

        for _ in range(n):
            updated = False
            for u, v, wt in edges:
                if distance[u] != INF and distance[u] + wt < distance[v]:
                    distance[v] = distance[u] + wt
                    updated = True
            if not updated:
                break

        negative_cycle = False
        for u, v, wt in edges:
            if distance[u] != INF and distance[u] + wt < distance[v]:
                negative_cycle = True
                break

        return [-1] if negative_cycle else distance

