        if flights is None:
            flights = []
        if n <= 0:
            return -1
        if src == dst:
            return 0
        if not (0 <= src < n) or not (0 <= dst < n):
            return -1
        adj = [[] for _ in range(n)]
        for u, v, w in flights:
            adj[u].append((v, w))

        best = [float("inf")]

        def dfs(node: int, cost: int, stops_left: int) -> None:
            if cost >= best[0]:
                return
            if node == dst:
                best[0] = cost
                return
            if stops_left < 0:
                return
            for v, w in adj[node]:
                dfs(v, cost + w, stops_left - 1)

        dfs(src, 0, k)
        return best[0] if best[0] != float("inf") else -1

