from typing import List, Optional, Dict, Set, Tuple

class Solution:
    def largestIsland(self, grid: List[List[int]] = None) -> int:
        if not grid or not grid[0]:
            return 0
        n = len(grid)
        m = len(grid[0])

        # Label every existing island (cells strictly equal to 1) with a
        # component id and record each component's size via a plain BFS.
        comp_id = [[-1] * m for _ in range(n)]
        comp_size = []
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1 and comp_id[i][j] == -1:
                    cid = len(comp_size)
                    stack = [(i, j)]
                    comp_id[i][j] = cid
                    size = 0
                    while stack:
                        x, y = stack.pop()
                        size += 1
                        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 1 and comp_id[nx][ny] == -1:
                                comp_id[nx][ny] = cid
                                stack.append((nx, ny))
                    comp_size.append(size)

        ans = max(comp_size) if comp_size else 1

        # Try flipping every water cell (strictly equal to 0) and sum up the
        # sizes of the distinct neighboring islands it would connect.
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 0:
                    seen = set()
                    total = 1
                    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 1:
                            cid = comp_id[ni][nj]
                            if cid not in seen:
                                seen.add(cid)
                                total += comp_size[cid]
                    ans = max(ans, total)
        return ans

