from typing import List


class Solution:
    def spanningTree(self, n: int = 0, adj: List[List[int]] = None):
        if adj is None:
            adj = []
        edges = []
        for i in range(n):
            for v, wt in adj[i]:
                edges.append((wt, i, v))
        edges.sort()

        tree_adj = [[] for _ in range(n)]

        def connected(u, v):
            # naive BFS/DFS reachability check instead of a disjoint set
            visited = [False] * n
            stack = [u]
            visited[u] = True
            while stack:
                node = stack.pop()
                if node == v:
                    return True
                for nxt in tree_adj[node]:
                    if not visited[nxt]:
                        visited[nxt] = True
                        stack.append(nxt)
            return False

        mst = 0
        edges_used = 0
        for wt, u, v in edges:
            if edges_used == n - 1:
                break
            if not connected(u, v):
                tree_adj[u].append(v)
                tree_adj[v].append(u)
                mst += wt
                edges_used += 1
        return mst

