            return 0
        visited = [False] * n
        key = [float("inf")] * n
        key[0] = 0
        mst = 0
        for _ in range(n):
            # naive O(n) linear scan for the minimum key node instead of a heap
            u = -1
            for i in range(n):
                if not visited[i] and (u == -1 or key[i] < key[u]):
                    u = i
            if u == -1 or key[u] == float("inf"):
