from typing import List


class Solution:
    def countPaths(self, n: int = 0, roads: List[List[int]] = None) -> int:
        MOD = 10 ** 9 + 7
        if roads is None:
            roads = []
        if n <= 0:
            return 0
        INF = float("inf")
        adj = [[] for _ in range(n)]
        for u, v, wt in roads:
            adj[u].append((v, wt))
            adj[v].append((u, wt))

        # Step 1: naive Bellman-Ford relaxation to find shortest distances
        dist = [INF] * n
        dist[0] = 0
        for _ in range(n):
            updated = False
            for u in range(n):
                if dist[u] == INF:
                    continue
                for v, wt in adj[u]:
                    if dist[u] + wt < dist[v]:
                        dist[v] = dist[u] + wt
                        updated = True
            if not updated:
                break

        # Step 2: count number of shortest paths, processing nodes in
        # increasing order of distance so every contributor is finalized
        # before it is used.
        order = sorted(range(n), key=lambda x: dist[x])
        ways = [0] * n
        ways[0] = 1
        for u in order:
            if dist[u] == INF:
                continue
            for v, wt in adj[u]:
                if dist[u] + wt == dist[v]:
                    ways[v] = (ways[v] + ways[u]) % MOD

        return ways[n - 1] % MOD

