        if times is None:
            times = []
        INF = float("inf")
        dist = [INF] * (n + 1)
        if 0 <= k <= n:
            dist[k] = 0
        # naive Bellman-Ford: relax all edges n-1 times instead of using a heap
        for _ in range(max(n - 1, 0)):
            updated = False
            for u, v, w in times:
                if dist[u] != INF and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    updated = True
            if not updated:
                break
        tail = dist[1:n + 1]
        if not tail:
            return -1
        ans = max(tail)
        return ans if ans < INF else -1

