from typing import List


class Solution:
    def findTheCity(self, n: int = 0, edges: List[List[int]] = None, threshold: int = 0) -> int:
        if edges is None:
            edges = []
        if n <= 0:
            return 0
        INF = float("inf")
        adj = [[] for _ in range(n)]
        for u, v, wt in edges:
            adj[u].append((v, wt))
            adj[v].append((u, wt))

        def dijkstra(src):
            # naive O(n) linear-scan Dijkstra instead of Floyd-Warshall
            dist = [INF] * n
            dist[src] = 0
            visited = [False] * n
            for _ in range(n):
                u = -1
                for i in range(n):
                    if not visited[i] and (u == -1 or dist[i] < dist[u]):
                        u = i
                if u == -1 or dist[u] == INF:
                    break
                visited[u] = True
                for v, wt in adj[u]:
                    if dist[u] + wt < dist[v]:
                        dist[v] = dist[u] + wt
            return dist

        cnt = [0] * n
        for i in range(n):
            dist = dijkstra(i)
            for j in range(n):
                if i != j and dist[j] <= threshold:
                    cnt[i] += 1

        res = min(cnt)
        ans = 0
        for i, c in enumerate(cnt):
            if c == res:
                ans = i
        return ans

