        n = len(grid)
        m = len(grid[0]) if n else 0
        grid = [row[:] for row in grid]
        minutes = 0
        # naive minute-by-minute full-grid simulation instead of multi-source BFS
        while True:
            fresh_exists = any(cell == 1 for row in grid for cell in row)
            if not fresh_exists:
                break
            to_rot = []
            for i in range(n):
                for j in range(m):
                    if grid[i][j] == 2:
                        for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 1:
                                to_rot.append((ni, nj))
            if not to_rot:
                return -1
            for ni, nj in to_rot:
                grid[ni][nj] = 2
            minutes += 1
        return minutes

