class Solution:
    def topoSort(self, n: int = 0, adj: List[List[int]] = None):
        if adj is None:
            adj = []
        visited = [False] * n
        order = []
        # naive iterative (explicit-stack) DFS postorder instead of recursion
        for start in range(n):
            if visited[start]:
                continue
            stack = [[start, 0]]
            visited[start] = True
            while stack:
                node, idx = stack[-1]
                neighbors = adj[node]
                if idx < len(neighbors):
                    stack[-1][1] += 1
                    nxt = neighbors[idx]
                    if not visited[nxt]:
                        visited[nxt] = True
                        stack.append([nxt, 0])
                else:
                    order.append(node)
                    stack.pop()
        return order[::-1]

