from typing import List
from collections import deque


class Solution:
    def ladderLength(self, begin: str = "", end: str = "", wordList: List[str] = None) -> int:
        if wordList is None:
            wordList = []
        words = list(dict.fromkeys(wordList))
        if end not in words:
            return 0
        if begin not in words:
            words = [begin] + words

        def one_diff(a, b):
            if len(a) != len(b):
                return False
            diff = 0
            for x, y in zip(a, b):
                if x != y:
                    diff += 1
                    if diff > 1:
                        return False
            return diff == 1

        n = len(words)
        # naive O(n^2) pairwise comparison to build the graph instead of
        # generating all 26-letter substitutions per position
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                if one_diff(words[i], words[j]):
                    adj[i].append(j)
                    adj[j].append(i)

        begin_idx = words.index(begin)
        end_idx = words.index(end)

        dist = [-1] * n
        dist[begin_idx] = 1
        queue = deque([begin_idx])
        while queue:
            u = queue.popleft()
            if u == end_idx:
                return dist[u]
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return 0

