        n = len(arr)
        best_len = 0
        best_count = 0

        def backtrack(i, prev_val, length):
            nonlocal best_len, best_count
            if i == n:
                if length > best_len:
                    best_len = length
                    best_count = 1
                elif length == best_len:
                    best_count += 1
                return
            backtrack(i + 1, prev_val, length)
            if prev_val is None or arr[i] > prev_val:
