class Solution:
    def all_longest_common_subsequences(self, s: str, t: str):
        n, m = len(s), len(t)
        dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if s[i - 1] == t[j - 1]:
                    dp[i][j] = 1 + dp[i - 1][j - 1]
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        def backtrack(i, j):
            if i == 0 or j == 0:
                return {""}
            if s[i - 1] == t[j - 1]:
                return {seq + s[i - 1] for seq in backtrack(i - 1, j - 1)}
            results = set()
            if dp[i - 1][j] >= dp[i][j - 1]:
                results |= backtrack(i - 1, j)
            if dp[i][j - 1] >= dp[i - 1][j]:
                results |= backtrack(i, j - 1)
            return results

        all_seqs = backtrack(n, m)
        max_len = max((len(seq) for seq in all_seqs), default=0)
        return sorted(seq for seq in all_seqs if len(seq) == max_len)

