class Solution:
    def shortestCommonSupersequence(self, s: str, t: str) -> str:
        n, m = len(s), len(t)

        def lcs(i, j):
            if i == 0 or j == 0:
                return 0
            if s[i - 1] == t[j - 1]:
                return 1 + lcs(i - 1, j - 1)
            return max(lcs(i - 1, j), lcs(i, j - 1))

        ans = []
        i, j = n, m
        while i > 0 and j > 0:
            if s[i - 1] == t[j - 1]:
                ans.append(s[i - 1])
                i -= 1
                j -= 1
            else:
                if lcs(i - 1, j) >= lcs(i, j - 1):
                    ans.append(s[i - 1])
                    i -= 1
                else:
                    ans.append(t[j - 1])
                    j -= 1
        while i > 0:
            ans.append(s[i - 1])
            i -= 1
        while j > 0:
            ans.append(t[j - 1])
            j -= 1
        return "".join(reversed(ans))

