from typing import List, Optional, Dict, Set, Tuple
import functools

class Solution:
    def __init__(self, val: str = '#') -> None:
        self.val = val

    def minValidStrings(self, words: List[str], target: str) -> int:
        n = len(target)

        def is_prefix_of_some_word(s: str) -> bool:
            for w in words:
                if w.startswith(s):
                    return True
            return False

        @functools.lru_cache(maxsize=None)
        def dp(i: int):
            if i == n:
                return 0
            best = float('inf')
            for j in range(i + 1, n + 1):
                if is_prefix_of_some_word(target[i:j]):
                    sub = dp(j)
                    if sub != float('inf'):
                        best = min(best, 1 + sub)
            return best

        res = dp(0)
        dp.cache_clear()
        return res if res != float('inf') else -1

