from typing import List, Optional, Dict, Set, Tuple

class Solution:
    def solve(self):
        # Self-contained brute-force Word Search II: no trie, just DFS per word.
        board = [
            ["o", "a", "a", "n"],
            ["e", "t", "a", "e"],
            ["i", "h", "k", "r"],
            ["i", "f", "l", "v"],
        ]
        words = ["oath", "pea", "eat", "rain"]
        rows, cols = len(board), len(board[0])

        def exists(word: str) -> bool:
            def dfs(r: int, c: int, idx: int, visited: set) -> bool:
                if idx == len(word):
                    return True
                if r < 0 or r >= rows or c < 0 or c >= cols:
                    return False
                if (r, c) in visited or board[r][c] != word[idx]:
                    return False
                visited.add((r, c))
                found = (
                    dfs(r + 1, c, idx + 1, visited)
                    or dfs(r - 1, c, idx + 1, visited)
                    or dfs(r, c + 1, idx + 1, visited)
                    or dfs(r, c - 1, idx + 1, visited)
                )
                visited.remove((r, c))
                return found

            for i in range(rows):
                for j in range(cols):
                    if dfs(i, j, 0, set()):
                        return True
            return False

        result = [w for w in words if exists(w)]
        return sorted(result)

